CREATE TABLE units (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies(id), name_ar text NOT NULL, symbol text NOT NULL, UNIQUE(company_id,symbol));
CREATE TABLE item_categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies(id), name_ar text NOT NULL, inventory_account_id uuid REFERENCES accounts(id), cogs_account_id uuid REFERENCES accounts(id), revenue_account_id uuid REFERENCES accounts(id));
CREATE TABLE items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies(id), sku text NOT NULL, name_ar text NOT NULL, item_type text NOT NULL CHECK(item_type IN ('STOCK','SERVICE')), unit_id uuid REFERENCES units(id), category_id uuid REFERENCES item_categories(id), reorder_level numeric(19,4) NOT NULL DEFAULT 0, costing_method text NOT NULL DEFAULT 'MOVING_AVERAGE' CHECK(costing_method IN ('MOVING_AVERAGE','FIFO')), is_active boolean NOT NULL DEFAULT true, UNIQUE(company_id,sku));
CREATE TABLE warehouses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies(id), code text NOT NULL, name_ar text NOT NULL, is_active boolean NOT NULL DEFAULT true, UNIQUE(company_id,code));
CREATE TABLE inventory_movements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies(id), item_id uuid NOT NULL REFERENCES items(id), warehouse_id uuid NOT NULL REFERENCES warehouses(id), movement_date date NOT NULL, movement_type text NOT NULL CHECK(movement_type IN ('PURCHASE','SALE','RETURN_IN','RETURN_OUT','TRANSFER_IN','TRANSFER_OUT','ADJUSTMENT')), quantity_delta numeric(19,4) NOT NULL CHECK(quantity_delta<>0), unit_cost numeric(19,4) NOT NULL CHECK(unit_cost>=0), source_type text NOT NULL, source_id uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX inventory_item_warehouse ON inventory_movements(item_id,warehouse_id,movement_date);
CREATE TABLE purchase_invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies(id), supplier_id uuid NOT NULL REFERENCES parties(id), invoice_no text NOT NULL, supplier_invoice_no text, invoice_date date NOT NULL, due_date date NOT NULL, subtotal numeric(19,4) NOT NULL CHECK(subtotal>=0), tax_total numeric(19,4) NOT NULL CHECK(tax_total>=0), total numeric(19,4) NOT NULL CHECK(total>=0), status text NOT NULL CHECK(status IN ('DRAFT','POSTED','VOID')), journal_entry_id uuid REFERENCES journal_entries(id), UNIQUE(company_id,invoice_no));
CREATE TABLE purchase_invoice_lines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), purchase_invoice_id uuid NOT NULL REFERENCES purchase_invoices(id) ON DELETE RESTRICT, line_no integer NOT NULL, item_id uuid REFERENCES items(id), description text NOT NULL, quantity numeric(19,4) NOT NULL CHECK(quantity>0), unit_price numeric(19,4) NOT NULL CHECK(unit_price>=0), discount_amount numeric(19,4) NOT NULL DEFAULT 0 CHECK(discount_amount>=0), tax_code_id uuid, UNIQUE(purchase_invoice_id,line_no));
CREATE TABLE payables (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies(id), supplier_id uuid NOT NULL REFERENCES parties(id), purchase_invoice_id uuid REFERENCES purchase_invoices(id), due_date date NOT NULL, original_amount numeric(19,4) NOT NULL CHECK(original_amount>0), open_amount numeric(19,4) NOT NULL CHECK(open_amount>=0), status text NOT NULL CHECK(status IN ('OPEN','PARTIAL','PAID','VOID')));
